document.querySelector('main').insertAdjacentHTML('beforeend',`<section class="view" id="ground"><div class="card"><h3>法域与题库状态</h3><select id="jurisdiction" class="sel"><option value="CN">中国 ESG 企业实务</option><option value="EU">EU / CBAM</option><option value="INT">国际</option><option value="TW">台湾地区</option><option value="ALL">综合</option></select><p id="gtCounts"></p><p>既有题目与知识点保留，来源版本、条款与生效日期尚未逐题核验。原刷题与模考为本地练习，成绩不作为认证结果。</p><button class="btn soft" id="exportGT">导出 Ground Truth 数据</button> <button class="btn soft" id="exportPrompt">导出 AI 出题指令</button> <button class="btn soft" id="exportProgress">导出进度备份</button><label class="btn soft">恢复 V3.1 备份<input type="file" id="restoreProgress" accept="application/json" hidden></label></div><div class="card section"><h3>七种题型 · 交互演示</h3><p>以下为虚构工厂的流程与算术样例，仅用于验收交互，不属于官方法规定论。</p><select class="sel" id="demoType"></select><div id="demoQuestion"></div></div><div class="card section"><h3>知识点弱点与熟练度</h3><p>熟练度 = 最近 20 次作答正确率；少于 5 次标记为证据不足。旧版成绩保留，不补造逐题答案。</p><div id="mastery31"></div></div></section><section class="view" id="account"><div class="card"><h3>账户与云端连接</h3><p id="authStatus">未配置 Supabase · 本地访客模式</p><p>填写项目 URL 与公开 publishable / anon key。不得填写 service_role 或 secret key。</p><input class="search" id="sbUrl" placeholder="https://项目.supabase.co"><input class="search" id="sbKey" placeholder="公开 publishable / anon key"><button class="btn soft" id="connect31">连接</button><hr><input class="search" id="email31" type="email" autocomplete="username" placeholder="邮箱"><input class="search" id="password31" type="password" autocomplete="current-password" placeholder="密码"><button class="btn primary" id="login31">登录</button> <button class="btn soft" id="logout31">退出</button><p><button class="btn soft" id="forgot31">发送安全重设邮件</button></p><div id="recovery31" hidden><input class="search" id="newPassword31" type="password" autocomplete="new-password" placeholder="新密码（至少12位）"><button class="btn primary" id="reset31">保存新密码</button></div><button class="btn soft" id="sync31">备份我的进度到云端</button> <button class="btn soft" id="pull31">恢复我的云端进度</button><p id="cloudStatus"></p></div><div class="card section"><h3>内容治理管理端</h3><p id="role31">角色未验证，管理功能锁定。</p><div id="admin31" hidden><p>可将旧题结构上传为待审核草稿。发布审批必须补齐来源证据，由后端检查。</p><button class="btn primary" id="uploadDraft31">上传前 20 题为待审核草稿</button></div></div></section>`);
const el=id=>document.getElementById(id);
function download31(name,data){const url=URL.createObjectURL(new Blob([typeof data==='string'?data:JSON.stringify(data,null,2)],{type:'application/json;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
el('exportGT').onclick=()=>download31('System-ESG-Ground-Truth-v3.1.json',{schema_version:'3.1',...GT});
el('exportPrompt').onclick=()=>download31('System-ESG-Prompt-v3.1.txt',buildPrompt(el('jurisdiction').value));
el('exportProgress').onclick=()=>download31('System-ESG-progress-v3.1.json',{schema_version:'3.1',state});
function validState31(x){return x&&typeof x==='object'&&['answered','learned','wrong'].every(k=>x[k]&&typeof x[k]==='object'&&!Array.isArray(x[k]))&&Array.isArray(x.exams)&&Array.isArray(x.attempts)&&x.attempts.every(a=>a&&typeof a.knowledge_id==='string'&&typeof a.correct==='boolean');}
el('restoreProgress').onchange=async e=>{try{const file=e.target.files[0];if(!file||file.size>15000000)throw Error('备份过大或未选择');const data=JSON.parse(await file.text());if(data.schema_version!=='3.1'||!validState31(data.state))throw Error('备份格式错误');if(!confirm('将以备份替换当前用户进度；建议先导出。继续？'))return;state=data.state;save();renderMastery31();toast('已恢复当前用户进度');}catch(err){toast(err.message);}e.target.value='';};
function counts31(){const region=el('jurisdiction').value,rows=GT.questions.filter(q=>region==='ALL'||q.jurisdiction===region);el('gtCounts').textContent=`本法域 ${rows.length} 题；审核通过 ${rows.filter(q=>!validateQuestion(q).length).length} 题；默认中国模式。`;}
el('jurisdiction').onchange=counts31;counts31();
// Preserve legacy modes while adding jurisdiction filtering.
const originalStartPractice=startPractice,originalStratified=stratified;
function allowed31(q){const region=el('jurisdiction').value;return region==='ALL'||GT.questions.find(g=>g.question_id===q.id)?.jurisdiction===region;}
startPractice=function(custom){originalStartPractice((custom||QUESTIONS.filter(q=>(!pModule.value||q.module===pModule.value)&&(!pLevel.value||q.level===pLevel.value)&&(!pType.value||q.type===pType.value)&&(!pOrigin.value||q.origin===pOrigin.value))).filter(allowed31));};
stratified=function(n){return QUESTIONS.filter(allowed31).sort(()=>Math.random()-.5).slice(0,n);};
const oldStartExam=startExam;
startExam=function(n,min){if(!QUESTIONS.some(allowed31)){toast('当前法域暂无可练习题目');return;}if(exam.timer)clearInterval(exam.timer);oldStartExam(n,min);};
function record31(q,answer,correct,mode,extra={}){state.attempts??=[];const g=GT.questions.find(g=>g.question_id===q.id);state.attempts.push({attempt_id:crypto.randomUUID(),question_id:q.id,knowledge_id:g?.knowledge_id||'DEMO-KP',module_id:q.module||'DEMO',scenario_id:'SC-'+q.id,user_answer:answer??null,correct_answer:g?.correct_answer??q.answer,correct,error_reason:correct?null:(g?.question_type==='calculation'?'calculation':'concept'),mode,at:new Date().toISOString(),...extra});}
const oldChoosePractice=choosePractice;
choosePractice=function(i){if(selected!==null)return;const q=pool[pi%pool.length];record31(q,i,i===q.answer,'practice');oldChoosePractice(i);renderMastery31();};
const oldFinishExam=finishExam;
finishExam=function(){if(!exam.qs||exam.completed)return;exam.completed=true;exam.end=null;exam.qs.forEach(q=>record31(q,exam.ans[q.id],exam.ans[q.id]===q.answer,'exam'));oldFinishExam();renderMastery31();};
function masteryRows31(){const map=new Map();for(const a of state.attempts||[]){if(!map.has(a.knowledge_id))map.set(a.knowledge_id,[]);map.get(a.knowledge_id).push(a);}return [...map].map(([knowledge_id,a])=>{const recent=a.slice(-20),mastery=Math.round(100*recent.filter(x=>x.correct).length/recent.length);return {knowledge_id,attempts:a.length,wrong:recent.filter(x=>!x.correct).length,mastery,recommendation:recent.length<5?'继续练习以积累证据':mastery<80?'回补知识点后再练':'进入更高难度'};}).sort((a,b)=>a.mastery-b.mastery);}
function renderMastery31(){const rows=masteryRows31();el('mastery31').innerHTML=rows.length?rows.map(r=>`<div class="wrongrow"><b>${esc(GT.knowledge.find(k=>k.knowledge_id===r.knowledge_id)?.title||r.knowledge_id)}</b> · ${r.mastery}% · ${r.attempts} 次 · 最近错 ${r.wrong} 次<p>${r.recommendation}</p><button class="btn soft" data-kp="${esc(r.knowledge_id)}">回补与再练</button></div>`).join(''):'尚无 V3.1 逐题记录。完成练习后显示。';el('mastery31').querySelectorAll('[data-kp]').forEach(b=>b.onclick=()=>{const k=GT.knowledge.find(k=>k.knowledge_id===b.dataset.kp);if(!k){el('demoQuestion').scrollIntoView();return;}openModule(k.module_id);openKP(k.module_id,MODULES.find(m=>m.id===k.module_id).nodes.findIndex(n=>n[0]===k.title));});}
const demos=[{text:'工厂规定先核对电表原始记录再汇总。第一步应做什么？',options:['核对原始电表记录','直接发布总数'],answer:0},{text:'内部清单要求保存电量和排放因子。应保留哪些数据？',options:['电量','排放因子','午餐菜单'],answer:[0,1]},{text:'假设用电100 kWh，因子0.5 kg CO₂e/kWh，计算排放量（kg CO₂e，容差0.01）。',answer:50},{text:'记录表为100 × 0.5 = 500 kg CO₂e。错误在哪里？',options:['乘法结果','单位中的kg'],answer:0},{text:'内部流程规定：采集 → 核对 → 发布。请按正确顺序输入选项编号（用逗号分隔）。',options:['发布','采集','核对'],answer:[1,2,0]},{text:'电量表：一月100 kWh；二月150 kWh。合计是多少？',options:['250 kWh','50 kWh'],answer:0},{text:'案例：电量100 kWh，因子0.5 kg CO₂e/kWh；规定发布前必须核对。分问1：排放量（kg）；分问2：下一步填“核对”。',answer:{amount:50,action:'核对'}}];
el('demoType').innerHTML=GT_LABELS.map((s,i)=>`<option value="${i}">${s}</option>`).join('');
function renderDemo31(){const i=Number(el('demoType').value),q=demos[i];el('demoQuestion').innerHTML=`<p>${esc(q.text)}</p>`+([0,1,3,5].includes(i)?q.options.map((o,n)=>`<label style="display:block;padding:8px"><input name="demoChoice" type="${i===1?'checkbox':'radio'}" value="${n}"> ${esc(o)}</label>`).join(''):i===4?q.options.map((o,n)=>`<p>${n+1}. ${esc(o)}</p>`).join('')+'<input id="demoInput" class="search" placeholder="例如 2,3,1">':`<input id="demoInput" class="search" type="number" step="any" placeholder="输入数值">${i===6?'<input id="demoAction" class="search" placeholder="下一步">':''}`)+`<p><button class="btn primary" id="submitDemo">提交答案</button></p><p id="demoFeedback" role="status"></p>`;el('submitDemo').onclick=()=>{let answer,ok=false;if([0,1,3,5].includes(i)){const a=[...document.querySelectorAll('[name=demoChoice]:checked')].map(x=>Number(x.value));if(!a.length)return toast('请先作答');answer=i===1?a:a[0];ok=JSON.stringify(answer)===JSON.stringify(q.answer);}else{if(!el('demoInput').value.trim())return toast('请先作答');if(i===4){answer=el('demoInput').value.split(/[,，]/).map(x=>Number(x.trim())-1);ok=JSON.stringify(answer)===JSON.stringify(q.answer);}else if(i===6){answer={amount:Number(el('demoInput').value),action:el('demoAction').value.trim()};ok=Math.abs(answer.amount-50)<=0.01&&answer.action==='核对';}else{answer=Number(el('demoInput').value);ok=Number.isFinite(answer)&&Math.abs(answer-50)<=0.01;}}record31({id:'DEMO-'+i,answer:q.answer},answer,ok,'demo',{question_type:GT_TYPES[i],knowledge_id:'DEMO-KP-'+i,error_reason:ok?null:i===2?'calculation':'concept'});save();renderMastery31();el('demoFeedback').textContent=ok?'正确。已记录演示作答。':'不正确。请回看题干中的内部规则或公式后再试。';el('submitDemo').disabled=true;};}
el('demoType').onchange=renderDemo31;renderDemo31();renderMastery31();
let sb31=null,user31=null,role31=null,recovery31=false,authEpoch31=0;
function msg31(s){el('authStatus').textContent=s;}
async function applySession31(session){const epoch=++authEpoch31;user31=session?.user||null;role31=null;el('admin31').hidden=true;el('role31').textContent='角色未验证，管理功能锁定。';const nextKey='systemESG31:'+(user31?.id||'guest');if(nextKey!==LS){if(exam.timer)clearInterval(exam.timer);exam={};pool=[];LS=nextKey;state=readState(LS)||{answered:{},learned:{},wrong:{},exams:[],attempts:[]};updateDash();renderLearnList();renderMastery31();resetExam();el('examRun').classList.add('hidden');el('practiceCard').innerHTML='用户已切换，请重新开始练习。';}msg31(user31?'已登录 '+user31.email:'访客模式');if(!user31)return;const {data,error}=await sb31.from('esg_roles').select('role').eq('user_id',user31.id).maybeSingle();if(epoch!==authEpoch31)return;if(error){el('role31').textContent='角色查询失败，管理功能锁定。';return;}role31=data?.role||'learner';el('role31').textContent='服务器角色：'+role31;el('admin31').hidden=!['admin','reviewer'].includes(role31);}
function publicKey31(key){if(key.startsWith('sb_publishable_'))return true;try{const payload=JSON.parse(atob(key.split('.')[1].replace(/-/g,'+').replace(/_/g,'/')));return payload.role==='anon';}catch{return false;}}
async function connect31(){try{const url=new URL(el('sbUrl').value.trim()),key=el('sbKey').value.trim();if(url.protocol!=='https:'||!publicKey31(key))throw Error('请填写 HTTPS 项目地址及公开 key');if(sb31)throw Error('切换项目请刷新页面后连接');if(!window.supabase){await new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2.102.0/dist/umd/supabase.js';script.onload=resolve;script.onerror=()=>reject(Error('认证组件载入失败'));document.head.append(script);});}localStorage.setItem('systemESG31:config',JSON.stringify({url:url.origin,key}));sb31=window.supabase.createClient(url.origin,key,{auth:{flowType:'pkce',detectSessionInUrl:true}});sb31.auth.onAuthStateChange((event,session)=>{if(event==='PASSWORD_RECOVERY'&&session){recovery31=true;el('recovery31').hidden=false;go('account');}if(event==='SIGNED_OUT'){recovery31=false;el('recovery31').hidden=true;}setTimeout(()=>applySession31(session),0);});const {data,error}=await sb31.auth.getSession();if(error)throw error;await applySession31(data.session);}catch(e){msg31(e.message);}}
