function needCloud31(){if(!sb31)throw Error('请先连接 Supabase');}
function action31(fn){return async()=>{try{await fn();}catch(e){msg31(e.message||'操作失败');}};}
el('login31').onclick=action31(async()=>{needCloud31();try{const {error}=await sb31.auth.signInWithPassword({email:el('email31').value.trim(),password:el('password31').value});if(error)throw Error('登录失败，请检查凭据或稍后重试');}finally{el('password31').value='';}});
el('logout31').onclick=action31(async()=>{needCloud31();const {error}=await sb31.auth.signOut();if(error)throw error;await applySession31(null);});
el('forgot31').onclick=action31(async()=>{needCloud31();if(!/^https?:$/.test(location.protocol))throw Error('重设邮件需要部署后的 HTTP(S) 回跳地址，不能使用本地文件地址');const {error}=await sb31.auth.resetPasswordForEmail(el('email31').value.trim(),{redirectTo:location.origin+location.pathname});if(error)throw Error('重设请求未完成，请稍后重试');msg31('若此邮箱可用，将收到重设邮件。请在同一浏览器打开链接。');});
el('reset31').onclick=action31(async()=>{needCloud31();if(!recovery31||!user31)throw Error('需要有效的邮件恢复会话');const password=el('newPassword31').value;if(password.length<12)throw Error('新密码至少12位');try{const {error}=await sb31.auth.updateUser({password});if(error)throw error;recovery31=false;el('recovery31').hidden=true;await sb31.auth.signOut();msg31('密码已更新，请重新登录');}finally{el('newPassword31').value='';}});
el('sync31').onclick=action31(async()=>{needCloud31();if(!user31)throw Error('请先登录');const {error}=await sb31.from('esg_progress').upsert({user_id:user31.id,payload:state,updated_at:new Date().toISOString()});if(error)throw error;el('cloudStatus').textContent='云端备份成功（练习进度，非认证成绩）';});
el('pull31').onclick=action31(async()=>{needCloud31();if(!user31)throw Error('请先登录');const uid=user31.id,{data,error}=await sb31.from('esg_progress').select('payload').eq('user_id',uid).maybeSingle();if(error)throw error;if(user31?.id!==uid)throw Error('账户已变更');if(!data||!validState31(data.payload))throw Error('无有效云端进度');if(!confirm('以云端备份替换当前进度？'))return;state=data.payload;save();renderLearnList();renderMastery31();el('cloudStatus').textContent='云端进度已恢复';});
el('uploadDraft31').onclick=action31(async()=>{needCloud31();if(!user31||!['admin','reviewer'].includes(role31))throw Error('没有内容治理权限');const rows=GT.questions.slice(0,20).map(q=>({question_id:q.question_id,payload:q,review_status:'pending',verified:false}));const {error}=await sb31.from('esg_question_drafts').upsert(rows);if(error)throw error;msg31('已上传20题待审核草稿，未发布到正式题库');});
