function addV32Pilot(){for(const s of V32_SOURCES)if(!GT.sources.some(x=>x.source_id===s.source_id))GT.sources.push(s);for(const r of V32_Q){const [id,module_id,source_id,kid,type,difficulty,question,options,correct_answer,answer_basis]=r,s=V32_SOURCES.find(x=>x.source_id===source_id);if(!GT.knowledge.some(x=>x.knowledge_id===kid))GT.knowledge.push({knowledge_id:kid,module_id,title:kid,source_id,review_status:'approved'});const q={id,question_id:id,knowledge_id:kid,module_id,module:module_id,question_type:type,difficulty,question,options,correct_answer,source_id,source_title:s.source_title,source_authority:s.source_authority,source_version:s.source_version,source_clause:s.source_clause,valid_from:s.valid_from,answer_basis,verified:true,review_status:'approved',jurisdiction:s.jurisdiction,region:s.region,legacy:false,q:question,answer:correct_answer,level:difficulty,kp:kid,source:s.source_title,explain:answer_basis};GT.questions.push(q);GT.scenarios.push({scenario_id:'SC-'+id,question_id:id,knowledge_id:kid,context:question,review_status:'approved'});QUESTIONS.push(q);}}
