;(()=>{const allow={go,renderLearnList,startPractice,startExam,practiceWrong,openModule,openKP,markLearned,practiceKP,choosePractice,nextPractice,answerExam,examPrev,examNext,finishExam,resetExam};function args(text){const out=[];let i=0;while(i<text.length){while(/[\s,]/.test(text[i]))i++;if(i>=text.length)break;if(text[i]==='\"'||text[i]==="'"){const quote=text[i++];let value='';while(i<text.length&&text[i]!==quote){if(text[i]==='\\'&&i+1<text.length)i++;value+=text[i++];}if(text[i++]!==quote)throw Error('Unclosed argument');out.push(value);}else{let end=i;while(end<text.length&&text[end]!==',')end++;const raw=text.slice(i,end).trim();if(!/^-?\d+(?:\.\d+)?$/.test(raw))throw Error('Invalid argument');out.push(Number(raw));i=end;}}return out;}document.addEventListener('click',event=>{const target=event.target.closest('[data-onclick]');if(!target)return;const handler=target.getAttribute('data-onclick'),match=handler&&handler.match(/^([A-Za-z_$][\w$]*)\(([\s\S]*)\)$/);if(!match||typeof allow[match[1]]!=='function')return;event.preventDefault();try{allow[match[1]](...args(match[2]));}catch(error){console.error('Action failed',error);if(typeof toast==='function')toast('操作失败，请稍后重试');}});})();